CREATE OR REPLACE FUNCTION reporte.total_cliente(p_cliente text)
RETURNS numeric
LANGUAGE plpgsql
AS $$
DECLARE
    v_total numeric;
BEGIN
    WITH f AS (SELECT monto FROM facturas WHERE cliente_id = p_cliente)
    SELECT coalesce(sum(monto), 0) INTO v_total FROM f;
    RETURN v_total;
END;
$$
